"use client";
export default function Portfolio() {
  const projects = [{ name: "AI Provider OS", desc: "200 providers 181 free 50 adapters", link: "https://github.com/rpolicarpo100/AI_R" }, { name: "Landing Page", desc: "Moderna com Tailwind" }];
  return (
    <div className="min-h-screen bg-[#0a0a0f] text-white p-8 max-w-4xl mx-auto">
      <header className="text-center py-12">
        <h1 className="text-5xl font-bold">Olá, sou Dev AI</h1>
        <p className="text-slate-400 mt-4 text-xl">Construo apps com 200 providers — 181 free — OpenAI-compatible</p>
      </header>
      <section className="mt-12">
        <h2 className="text-2xl font-bold">Projetos</h2>
        <div className="grid grid-cols-2 gap-6 mt-6">
          {projects.map(p => (
            <a key={p.name} href={p.link} className="p-6 rounded-xl bg-[#11111b] border border-[#1e1e2e] hover:border-white transition">
              <div className="font-bold">{p.name}</div>
              <div className="text-slate-400 text-sm mt-2">{p.desc}</div>
            </a>
          ))}
        </div>
      </section>
    </div>
  );
}

